        }
        return context[top];
    }

    /**
     * Pops a diagnostic context from the stack.
     * @return String The diagnostic context that was removed.
     */
    public static String pop() {
        if (top < 0) {
            throw new IllegalStateException("NDC stack underflow");
        }
        String ctx = context[top];
        context[top] = null;
        top--;
